import { MakeLogicType, actions, defaults, kea, key, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'
import { subscriptions } from 'kea-subscriptions'

import api from 'lib/api'
import { ErrorEventType } from 'lib/components/Errors/types'
import { Dayjs, dayjs } from 'lib/dayjs'

import { DateRange, ErrorTrackingIssue } from '~/queries/schema/schema-general'

import { errorTrackingIssueQuery } from '../../queries'

export interface IssueEventSelectionLogicProps {
    issueId: ErrorTrackingIssue['id']
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueEventSelectionLogicValues {
    initialEvent: ErrorEventType | null
    initialEventLoading: boolean
    initialEventTimestamp: string | null
    selectedEvent: ErrorEventType | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueEventSelectionLogicActions {
    loadInitialEvent: (timestamp: string) => {
        timestamp: string
    }
    loadInitialEventFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadInitialEventSuccess: (
        initialEvent: ErrorEventType | null,
        payload?: {
            timestamp: string
        }
    ) => {
        initialEvent: ErrorEventType | null
        payload?: {
            timestamp: string
        }
    }
    selectEvent: (event: ErrorEventType | null) => {
        event: ErrorEventType | null
    }
    setInitialEventTimestamp: (timestamp: string | null) => {
        timestamp: string | null
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueEventSelectionLogicMeta {
    key: string
}

export type issueEventSelectionLogicType = MakeLogicType<
    issueEventSelectionLogicValues,
    issueEventSelectionLogicActions,
    IssueEventSelectionLogicProps,
    issueEventSelectionLogicMeta
>

export const issueEventSelectionLogic = kea<issueEventSelectionLogicType>([
    props({} as IssueEventSelectionLogicProps),
    key((props) => props.issueId),
    path((key) => ['products', 'error_tracking', 'scenes', 'ErrorTrackingIssueScene', 'issueEventSelectionLogic', key]),

    actions({
        loadInitialEvent: (timestamp: string) => ({ timestamp }),
        setInitialEventTimestamp: (timestamp: string | null) => ({ timestamp }),
        selectEvent: (event: ErrorEventType | null) => ({
            event,
        }),
    }),

    defaults({
        initialEvent: null as ErrorEventType | null,
        selectedEvent: null as ErrorEventType | null,
        initialEventTimestamp: null as string | null,
        initialEventLoading: true as boolean,
    }),

    reducers({
        initialEventTimestamp: {
            // A malformed `timestamp` URL param (truncated/mangled shared links, crawlers) would
            // otherwise be stored and fed to getNarrowDateRange, where dayjs().toISOString() throws
            // a RangeError on an Invalid Date. Ignore invalid values so we fall back to the valid
            // last_seen/first_seen the server provides, exactly as if no timestamp were passed.
            setInitialEventTimestamp: (state, { timestamp }) => {
                if (!state && timestamp && dayjs(timestamp).isValid()) {
                    return timestamp
                }
                return state
            },
        },
        selectedEvent: {
            selectEvent: (_, { event }) => event,
        },
    }),

    loaders(({ values, actions, props }) => ({
        initialEvent: {
            loadInitialEvent: async ({ timestamp }) => {
                // Guard the narrow-range formatting below: an invalid timestamp makes
                // getNarrowDateRange throw a RangeError. Treat it as "no initial event".
                if (!dayjs(timestamp).isValid()) {
                    return null
                }
                const response = await api.query(
                    errorTrackingIssueQuery({
                        issueId: props.issueId,
                        dateRange: getNarrowDateRange(timestamp),
                        filterTestAccounts: false,
                        withAggregations: false,
                        withFirstEvent: false,
                        withLastEvent: true,
                    }),
                    { refresh: 'blocking' }
                )
                const positionEvent = response.results[0]?.last_event
                if (!positionEvent) {
                    return null
                }
                const initialEvent: ErrorEventType = {
                    event: '$exception',
                    uuid: positionEvent.uuid,
                    distinct_id: positionEvent.distinct_id,
                    timestamp: positionEvent.timestamp,
                    person: { distinct_ids: [], properties: {} },
                    properties: JSON.parse(positionEvent.properties),
                }
                if (!values.selectedEvent) {
                    actions.selectEvent(initialEvent)
                }
                return initialEvent
            },
        },
    })),

    subscriptions(({ actions }) => ({
        initialEventTimestamp: (value: string | null, oldValue: string | null) => {
            if (!oldValue && value) {
                actions.loadInitialEvent(value)
            }
        },
    })),
])

function getNarrowDateRange(timestamp: Dayjs | string): DateRange {
    const firstSeen = dayjs(timestamp)
    return {
        date_from: firstSeen.subtract(1, 'hour').toISOString(),
        date_to: firstSeen.add(1, 'hour').toISOString(),
    }
}
